#!/usr/bin/env pwsh
# CS2 (Linux) pre-start setup. Runs impersonated as the per-service user on every
# BeforeServiceStarted event, just before TCAdmin launches the generated start.sh.
# Progress is printed with Write-Host so the run shows up in TCAdmin's service log.

$root    = $ThisService.RootDirectory
$gamedir = "$root/game"

Write-Host "[cs2-prestart] starting (user '$([Environment]::UserName)', root '$root')"

try {
    Set-Location -LiteralPath $gamedir -ErrorAction Stop
} catch {
    Write-Host "[cs2-prestart] ERROR: game directory not found: $gamedir"
    exit 1
}

# Set-Location moves PowerShell's location but not the process working directory that native
# commands (chmod) inherit; sync it so the relative paths below resolve in the game directory.
[Environment]::CurrentDirectory = $PWD.ProviderPath
Write-Host "[cs2-prestart] working dir: $($PWD.ProviderPath)"

# 1) DepotDownloader extracts the game files as 0644, so the cs2 binary loses its execute bit
#    and "./bin/linuxsteamrt64/cs2" dies with "Permission denied". Restore it on every start
#    so it also self-heals after a game update re-extracts the files.
$cs2 = "bin/linuxsteamrt64/cs2"
if (Test-Path -LiteralPath $cs2) {
    chmod +x $cs2 2>$null; $rc = $LASTEXITCODE
    if ($rc -eq 0) { Write-Host "[cs2-prestart] set execute bit on $cs2" }
    else           { Write-Host "[cs2-prestart] WARNING: chmod on $cs2 exited $rc" }
} else {
    Write-Host "[cs2-prestart] WARNING: $cs2 not found - skipping chmod"
}

# 2) The Steam Game Server API dlopen()s steamclient.so from $HOME/.steam/sdk{32,64}; without
#    it cs2 segfaults right after engine init. The per-service user has no writable /home dir,
#    so we point HOME at the service root (below) and stage steamclient.so there from the
#    monitor's bundled SteamCMD tools, falling back to the shared game account's copy.
function Stage-SteamClient {
    param(
        [string] $Arch,   # linux64 | linux32
        [string] $Sdk     # sdk64   | sdk32
    )

    $dest = "$root/.steam/$Sdk/steamclient.so"
    if (Test-Path -LiteralPath $dest) {
        Write-Host "[cs2-prestart] steamclient.so already present for $Sdk - skipping"
        return
    }

    New-Item -ItemType Directory -Path "$root/.steam/$Sdk" -Force | Out-Null

    $sources = @(
        "/opt/tcadmin3/components/monitor/Assets/Tools/SteamCmd/$Arch/steamclient.so"
        "/home/tca3game/.steam/$Sdk/steamclient.so"
    )
    foreach ($src in $sources) {
        if (Test-Path -LiteralPath $src) {
            try {
                Copy-Item -LiteralPath $src -Destination $dest -Force -ErrorAction Stop
                Write-Host "[cs2-prestart] staged steamclient.so for $Sdk from $src"
                return
            } catch {
                Write-Host "[cs2-prestart] WARNING: copy from $src failed: $($_.Exception.Message)"
            }
        }
    }
    Write-Host "[cs2-prestart] WARNING: could not stage steamclient.so for $Sdk (no readable source)"
}
Stage-SteamClient -Arch linux64 -Sdk sdk64
Stage-SteamClient -Arch linux32 -Sdk sdk32

# 3) Write the launch script TCAdmin executes. Only HOME is expanded here (by PowerShell) so the
#    running server resolves ~/.steam/sdk64/steamclient.so to the copy staged above; ${PATH},
#    $HOME and $LD_LIBRARY_PATH are kept literal for bash to expand at runtime.
$filename = "bin/linuxsteamrt64/start.sh"
$startLines = @(
    '#!/bin/bash'
    "export HOME='$root'"
    'export PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:/usr/games:/usr/local/games:/snap/bin:${PATH}'
    'export LD_LIBRARY_PATH=./bin/linuxsteamrt64:$HOME/.steam/sdk64:$LD_LIBRARY_PATH'
    './bin/linuxsteamrt64/cs2 $*'
)
# Join with LF and write UTF-8 without a BOM so the shebang stays the first bytes.
Set-Content -LiteralPath $filename -Value (($startLines -join "`n") + "`n") -NoNewline -Encoding utf8NoBOM
Write-Host "[cs2-prestart] wrote ${filename}:"
foreach ($line in $startLines) { Write-Host "    $line" }

chmod +x $filename 2>$null; $rc = $LASTEXITCODE
if ($rc -eq 0) { Write-Host "[cs2-prestart] set execute bit on $filename" }
else           { Write-Host "[cs2-prestart] WARNING: chmod on $filename exited $rc" }

Write-Host "[cs2-prestart] done"
exit 0

//refAssemblies: TCAdmin.Web.Shared.dll, OpenGSQ.dll
using System;
using System.Text.RegularExpressions;
using OpenGSQ.Protocols;
using OpenGSQ.Responses.Source;
using TCAdmin.SDK.Hubs.Models.GameQuery;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Custom query protocol (bound to CustomQueryProtocol).
//
// V2 returned a qstat-style XML string. V3's custom_script provider instead JSON-serializes the
// script's ReturnValue and deserializes it into a GameQueryResponse (see
// CustomScriptQuery.cs), so we build and return that object directly with the same data the
// V2 XML carried: name, gametype, map, players, rules and the game_tag cp/mp override.
//
// The provider injects Address/Port for the service being queried.
var address = ThisService.Variables.Parse<string>("Address") ?? ThisService.IPAddress;
var port = ThisService.Variables.ContainsKey("Port")
    ? ThisService.Variables.Parse<int>("Port")
    : ThisService.QueryPort;

try
{
    // Rust answers the Source (A2S) query protocol.
    var source = new Source(address, port, 5000);
    var info = await source.GetInfo();
    var players = await source.GetPlayers();
    var rules = await source.GetRules();

    var response = new GameQueryResponse
    {
        Success = true,
        Status = "UP",
        Protocol = "custom_script",
        Address = address,
        Hostname = $"{address}:{port}",
        Name = info.Name,
        GameType = info.Game,
        Map = info.Map,
        NumPlayers = info.Players,
        MaxPlayers = info.MaxPlayers,
        NumSpectators = 0,
        MaxSpectators = 0,
        Retries = 0
    };

    if (rules != null)
    {
        foreach (var rule in rules)
            response.Rules[rule.Key] = rule.Value;
    }

    if (players != null)
    {
        foreach (var player in players)
        {
            response.Players.Add(new GameQueryPlayer
            {
                Name = player.Name,
                // Source A2S exposes Score and Duration but not a per-player ping.
                Score = (int)player.Score,
                Ping = 0
            });
        }
    }

    // Rust reports real player/slot counts in the "game tag" (A2S keywords), e.g. "cp12,mp50".
    // Prefer the game_tag rule, falling back to the A2S keywords field on the info packet.
    var gameTag = response.Rules.TryGetValue("game_tag", out var tagFromRules) && !string.IsNullOrEmpty(tagFromRules)
        ? tagFromRules
        : (info as SourceInfo)?.Keywords ?? string.Empty;

    if (!string.IsNullOrEmpty(gameTag))
    {
        var cp = Regex.Match(gameTag, @"cp(\d+)");
        if (cp.Success)
            response.NumPlayers = int.Parse(cp.Groups[1].Value);

        var mp = Regex.Match(gameTag, @"mp(\d+)");
        if (mp.Success)
            response.MaxPlayers = int.Parse(mp.Groups[1].Value);
    }

    Globals.ReturnValue = response;
}
catch (Exception ex)
{
    // Returning an offline response keeps the query subsystem happy when the server is down.
    Globals.ReturnValue = GameQueryResponse.DefaultOfflineResponse(address, "custom_script", ex.Message);
}

//refAssemblies: TCAdmin.Web.Shared.dll
// V2 origin: CS2 "Extract mapfile" (AfterCustomModInstalled).
//
// TWO important notes (read before deploying):
//
// 1) The V2 script contained an UNCONDITIONAL `raise Exception()` placed BEFORE the
//    extract logic, so it always failed — it was a disabled / debugging-leftover
//    script. This port restores the INTENDED behavior (install the workshop map).
//    If the intent really was to hard-fail the AfterCustomModInstalled event, delete
//    this script instead of attaching it.
//
// 2) Same V2->V3 model change as the CS:GO version: V2's single-blob `FileNameSavePath`
//    /`FileNameNoPath` variables DO NOT EXIST in V3. The workshop pipeline downloads the
//    item already-extracted into the directory `Dynamic.InstallPath`. CS2's maps folder
//    is game/csgo/maps (note the extra `game` segment vs CS:GO).
using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

async Task ReportProgress(int? progress, string log = null)
{
    if (ThisTaskStepHandler != null)
        await ThisTaskStepHandler.UpdateProgress(progress, log);
    else if (!string.IsNullOrEmpty(log))
        ScriptConsole.WriteLine(log);
}

string fileTitle = (string)Dynamic.FileTitle;
await ReportProgress(null, fileTitle);

string installPath = (string)Dynamic.InstallPath;
if (string.IsNullOrEmpty(installPath) || !Directory.Exists(installPath))
{
    throw new Exception($"Workshop install path was not found: {installPath ?? "(null)"}");
}

string mapsFolder = Path.Combine(ThisService.RootDirectory, "game", "csgo", "maps");
Directory.CreateDirectory(mapsFolder);

string[] mapExtensions = { ".bsp", ".nav", ".ain", ".txt", ".vpk" };

var mapFiles = Directory
    .EnumerateFiles(installPath, "*", SearchOption.AllDirectories)
    .Where(f => mapExtensions.Contains(Path.GetExtension(f), StringComparer.OrdinalIgnoreCase))
    .ToList();

if (mapFiles.Count == 0)
{
    throw new Exception($"No map files (.bsp/.nav/.ain/.txt/.vpk) were found in {installPath}.");
}

foreach (var sourceFile in mapFiles)
{
    var destFile = Path.Combine(mapsFolder, Path.GetFileName(sourceFile));
    try
    {
        File.Copy(sourceFile, destFile, true);
        ScriptConsole.WriteLine($"Installed map file: game/csgo/maps/{Path.GetFileName(sourceFile)}");
    }
    catch (IOException e)
    {
        throw new Exception($"Failed to install game/csgo/maps/{Path.GetFileName(sourceFile)}, error was:\n{e.Message}");
    }
}

//refAssemblies: TCAdmin.Web.Shared.dll
// V2 origin: CS2 "Uninstall workshop mods" (AfterCustomModUninstalled).
//
// V2 deleted game/csgo/maps/<FileNameNoPath>. V3 has NO `FileNameNoPath` variable.
//
// Note: in V3 the workshop UNINSTALL pipeline already deletes every file that was
// tracked when the item was installed (see BaseWorkshopFileTaskStepHandler.
// UninstallWorkshopFile). The companion install script (396) copies the map assets
// into game/csgo/maps and those copies are tracked, so the pipeline normally removes
// them on its own and this event is largely redundant.
//
// Kept as a best-effort safety net: derive map file names from the workshop item
// directory (Dynamic.InstallPath) and remove any matching files still present in
// game/csgo/maps. CS2's maps folder has the extra `game` segment vs CS:GO.
using System;
using System.IO;
using System.Linq;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

string mapsFolder = Path.Combine(ThisService.RootDirectory, "game", "csgo", "maps");
string installPath = (string)Dynamic.InstallPath;

if (string.IsNullOrEmpty(installPath) || !Directory.Exists(installPath))
{
    ScriptConsole.WriteLine($"Workshop item directory not present ({installPath ?? "(null)"}); nothing to remove from game/csgo/maps.");
    return;
}

string[] mapExtensions = { ".bsp", ".nav", ".ain", ".txt", ".vpk" };

var mapFileNames = Directory
    .EnumerateFiles(installPath, "*", SearchOption.AllDirectories)
    .Where(f => mapExtensions.Contains(Path.GetExtension(f), StringComparer.OrdinalIgnoreCase))
    .Select(Path.GetFileName)
    .Distinct();

foreach (var fileName in mapFileNames)
{
    var mapFile = Path.Combine(mapsFolder, fileName);
    try
    {
        if (File.Exists(mapFile))
        {
            File.Delete(mapFile);
            ScriptConsole.WriteLine($"Removed map file: game/csgo/maps/{fileName}");
        }
    }
    catch (IOException e)
    {
        throw new Exception($"Failed to delete game/csgo/maps/{fileName}, error was:\n{e.Message}");
    }
}

using System.IO;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

var root = Globals.ThisService.RootDirectory;
var backupRoot = Path.Combine(root, "__tca_cfg_backup");
if (Directory.Exists(backupRoot)) Directory.Delete(backupRoot, true);
Directory.CreateDirectory(backupRoot);

var configFiles = Globals.ThisGame.ConfigFiles;
Globals.ScriptConsole.WriteLine("Config backup: " + (configFiles == null ? 0 : configFiles.Count) + " config file(s) defined for this game.");
int n = 0;
if (configFiles != null)
{
    foreach (var cf in configFiles)
    {
        if (string.IsNullOrWhiteSpace(cf.RelativePath)) continue;
        var rel = cf.RelativePath.Replace('\\', Path.DirectorySeparatorChar).Replace('/', Path.DirectorySeparatorChar).TrimStart(Path.DirectorySeparatorChar);
        var src = Path.Combine(root, rel);
        if (!File.Exists(src)) { Globals.ScriptConsole.WriteLine("  skip (not on disk): " + rel); continue; }
        var dst = Path.Combine(backupRoot, rel);
        Directory.CreateDirectory(Path.GetDirectoryName(dst));
        File.Copy(src, dst, true);
        n++;
        Globals.ScriptConsole.WriteLine("  backed up: " + rel);
    }
}
Globals.ScriptConsole.WriteLine("Config backup complete: " + n + " file(s).");

using System.IO;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

var root = Globals.ThisService.RootDirectory;
var backupRoot = Path.Combine(root, "__tca_cfg_backup");
if (!Directory.Exists(backupRoot))
{
    Globals.ScriptConsole.WriteLine("Config restore: no backup found, nothing to restore.");
}
else
{
    var configFiles = Globals.ThisGame.ConfigFiles;
    int n = 0;
    if (configFiles != null)
    {
        foreach (var cf in configFiles)
        {
            if (string.IsNullOrWhiteSpace(cf.RelativePath)) continue;
            var rel = cf.RelativePath.Replace('\\', Path.DirectorySeparatorChar).Replace('/', Path.DirectorySeparatorChar).TrimStart(Path.DirectorySeparatorChar);
            var bak = Path.Combine(backupRoot, rel);
            if (!File.Exists(bak)) continue;
            var dst = Path.Combine(root, rel);
            Directory.CreateDirectory(Path.GetDirectoryName(dst));
            File.Copy(bak, dst, true);
            try { Globals.OperatingSystem.SetFileOwnerAutoDetect(dst); } catch { }
            n++;
            Globals.ScriptConsole.WriteLine("  restored: " + rel);
        }
    }
    try { Directory.Delete(backupRoot, true); } catch { }
    Globals.ScriptConsole.WriteLine("Config restore complete: " + n + " file(s) restored.");
}
